for (const [id, [proposedTitle, descriptionIntro]] of Object.entries(copy)) merged.set(id, {id, proposedTitle, descriptionIntro, copyBasis:id==='QnrKPMXAR54'?'existing title and live Studio description; linked primary project https://nvlabs.github.io/motionbricks/ checked; original description retained below':'existing video title and live Studio description where checked; original description retained below'});
